import{_ as r,c as t,o as l,ag as e}from"./chunks/framework.Bkod66qp.js";const b=JSON.parse('{"title":"기관성과급 시행 내규","description":"","frontmatter":{"title":"기관성과급 시행 내규","subtitle":"","doc_id":"","last_update":"2022-12-15","author":"","categories":[],"tags":[]},"headers":[],"relativePath":"regulation/405_기관성과급 시행 내규(221215).md","filePath":"regulation/405_기관성과급 시행 내규(221215).md"}'),n={name:"regulation/405_기관성과급 시행 내규(221215).md"};function o(s,a,i,d,c,h){return l(),t("div",null,a[0]||(a[0]=[e(`<h1 id="law-title" class="center" tabindex="-1">기관성과급 시행 내규 <a class="header-anchor" href="#law-title" aria-label="Permalink to &quot;기관성과급 시행 내규 {#law-title .center}&quot;">​</a></h1><div style="text-align:right;"><pre style="display:inline-block;margin:0;white-space:pre;font-family:monospace;">제정 2012.  10.  30
개정 2014.  11.  19
개정 2014.  12.  16
개정 2018.  11.  16
개정 2019.  11.  19
개정 2020.  12.  14
개정 2021.  12.  20
개정 2022.  12.  15</pre></div><h2 id="article1" class="sr-only" tabindex="-1">제1조 (목적) <a class="header-anchor" href="#article1" aria-label="Permalink to &quot;제1조 (목적) {#article1 .sr-only}&quot;">​</a></h2><p><strong>제1조(목적)</strong> 이 규칙은 재단법인서울문화재단(이하 “재단”이라 한다)의 보수규정 제18조의 1의 규정에 의하여 재단 정규직 및 계약직 직원(이하 “직원”이라 한다)에게 지급하는 기관성과급에 관한 세부사항을 규정함을 목적으로 한다. &lt;개정 2014. 11. 19.&gt;</p><h2 id="article2" class="sr-only" tabindex="-1">제2조 (적용범위) <a class="header-anchor" href="#article2" aria-label="Permalink to &quot;제2조 (적용범위) {#article2 .sr-only}&quot;">​</a></h2><p><strong>제2조(적용범위)</strong> 직원에게 지급하는 기관성과급의 지급범위 및 지급액에 관한 사항은 다른 규정에 특별한 규정이 있는 경우를 제외하고는 이 규칙이 정하는 바에 의한다.</p><h2 id="article3" class="sr-only" tabindex="-1">제3조 (지급기준) <a class="header-anchor" href="#article3" aria-label="Permalink to &quot;제3조 (지급기준) {#article3 .sr-only}&quot;">​</a></h2><p><strong>제3조(지급기준)</strong> 이 규칙에 의한 기관성과급은 예산의 범위 안에서 지급하고 남은 성과급 예산은 다른 용도로 전용을 금지한다.</p><h2 id="article4" class="sr-only" tabindex="-1">제4조 (지급일) <a class="header-anchor" href="#article4" aria-label="Permalink to &quot;제4조 (지급일) {#article4 .sr-only}&quot;">​</a></h2><p><strong>제4조(지급일)</strong> 이 규칙에 의한 기관성과급은 특별한 규정이 있는 경우를 제외하고는 경영평가결과를 확정 ‧ 통보받은 날부터 3월 이내로 한다.</p><h2 id="article5" class="sr-only" tabindex="-1">제5조 (지급방법 등) <a class="header-anchor" href="#article5" aria-label="Permalink to &quot;제5조 (지급방법 등) {#article5 .sr-only}&quot;">​</a></h2><p><strong>제5조(지급방법 등)</strong> ① 이 규칙에 의한 기관성과급은 특별한 규정이 있는 경우를 제외하고는 기준월액에 지급률을 곱하여 지급총액을 산출 후 이 총액 범위 내에서 지급한다.<br> ② “기준월액”이라 함은 개인월봉 금액을 말한다. &lt;개정 2022. 12. 15.&gt;<br> ③ 지급률은 각 등급별로 차등화하여 정한다.<br> ④ 등급은 개인근무평정을 100% 반영하여 각 등급별로 인원을 할당한다. &lt;개정 2018. 11. 16.&gt;<br> ⑤ 등급은 개인 또는 부서단위로 4등급이상으로 차등을 두며, 등급별 인원 비율도 최고는 20%이내, 최저는 10%이상으로 강제 배분한다. 단 특정 등급의 인원배분 비율이 50%를 초과하지 않도록 한다. &lt;개정 2014. 12. 16.&gt;<br> ⑥ 최고-최저 등급 간 지급률의 차이는 50%p 이상으로 한다.</p><h2 id="article6" class="sr-only" tabindex="-1">제6조 (경영평가TFT 포상) <a class="header-anchor" href="#article6" aria-label="Permalink to &quot;제6조 (경영평가TFT 포상) {#article6 .sr-only}&quot;">​</a></h2><p><strong>제6조(경영평가TFT 포상)</strong> ① 전년도 경영평가TFT 인원에게는 별도의 포상을 제공할 수 있으며, 포상의 내용과 성격은 매년 대표이사의 방침으로 정한다.<br> ② 삭제 &lt;2018. 11. 16.&gt;</p><h2 id="article7" class="sr-only" tabindex="-1">제7조 (지급대상기간) <a class="header-anchor" href="#article7" aria-label="Permalink to &quot;제7조 (지급대상기간) {#article7 .sr-only}&quot;">​</a></h2><p><strong>제7조(지급대상기간)</strong> 개인별 또는 부서단위 근무성적과 업무성과의 대상기간은 경영평가 대상기간의 1월 1일부터 12월 31일까지로 한다.</p><h2 id="article8" class="sr-only" tabindex="-1">제8조 (연도 중 입퇴사자) <a class="header-anchor" href="#article8" aria-label="Permalink to &quot;제8조 (연도 중 입퇴사자) {#article8 .sr-only}&quot;">​</a></h2><p><strong>제8조(연도 중 입퇴사자)</strong> ① 연도 중 입사자의 경우 평가대상 기간인 전년도에 적용되지 아니하므로 연도의 성과급 지급대상이 아니다.<br> ② 연도 중 퇴사자는 퇴직시점에서 직전년도 당사자의 지급률로 일할(평가대상 연도 1월 1일~퇴직일) 계산하여 지급한다. &lt;개정 2019.11.19.&gt;<br> ③ 다만, 퇴직시점에 직전년도 당사자의 지급률이 없고 당사자 사이에 합의가 있는 경우에는 전년도 경영평가가 완료되어 지급률이 결정된 후 지급이 가능하다.</p><h2 id="article9" class="sr-only" tabindex="-1">제9조 (성과급 지급대상 기간에서 제외) <a class="header-anchor" href="#article9" aria-label="Permalink to &quot;제9조 (성과급 지급대상 기간에서 제외) {#article9 .sr-only}&quot;">​</a></h2><p><strong>제9조(성과급 지급대상 기간에서 제외)</strong> ① 휴직(공무상 상해로 인한 휴직 제외), 직위해제, 교육훈련 파견, 장기병가(공무상 병가 제외), 징계 등의 사유로 실제로 직무에 종사하지 아니한 기간에 대하여는 일할계산에 의하여 제외한다. &lt;개정 2019.11.19.&gt;<br> ② 다만, 평가기간 중 1개월 미만의 기간(교육파견의 경우 2개월)에 대하여는 제외하지 아니한다.</p><h2 id="article10" class="sr-only" tabindex="-1">제10조 (성과급 미지급 대상) <a class="header-anchor" href="#article10" aria-label="Permalink to &quot;제10조 (성과급 미지급 대상) {#article10 .sr-only}&quot;">​</a></h2><p><strong>제10조(성과급 미지급 대상)</strong> 다음 각 호에 해당하는 경우 성과급을 지급할 수 없다. &lt;신설 2020.12.14.&gt;</p><ol><li>비리 등으로 사회적 물의를 일으켜 사퇴하거나 형이 확정된 자</li><li>임원 비리가 발생한 기관의 기관장</li><li>사업성과가 없어 경영평가를 받지 않는 기관의 모든 임직원</li><li>「기관장 성과계약 이행실적 평가」 결과 C, D등급을 받은 기관장</li><li>「기관 경영평가」 결과 최하등급(‘라’등급) 기관장 및 직원</li><li>평가대상기간 중 다음 징계 사유의 비위가 발생하였거나 징계를 받은 경우<br> 가. 기간 중 중징계 처분(파면, 해임, 강등, 정직)을 받은 자<br> 나. 「국가공무원법」 제83조의2 제1항(금품수수, 향응수수, 횡령) 등에 따른 징계 사유의 시효가 5년인 비위<br> 다. 「성폭력범죄의 처벌 등에 관한 특례법」(추행, 간음 등)에 따른 성폭력범죄<br> 라. 「성매매알선 등 행위의 처벌에 관한 법률」 에 따른 성매매<br> 마. 「국가인권위원회법」 제2조 제3호 라목에 따른 성희롱(업무 등의 관계에서 공공기관의 종사자 등이 그 직위를 이용해 성적 굴욕감을 느끼게 하는 행위 등)<br> 바. 「도로교통법」 제44조 제1항9술에 취한 상태에서의 운전금지)에 따른 음주운전에 대한 징계</li><li>입사일로부터 퇴사일까지 근무기간이 3개월 미만인 자(1개월은 30일로 계산) &lt;신설 2021.12.20.&gt;</li></ol><h2 id="addendum1" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum1" aria-label="Permalink to &quot;부칙 {#addendum1 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2012. 10. 30.&gt;<br> 제1조(시행일) 본 내규는 대표이사가 확정한 날부터 시행한다.</p><h2 id="addendum2" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum2" aria-label="Permalink to &quot;부칙 {#addendum2 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2014. 11. 19.&gt;<br> 제1조(시행일) 본 내규는 대표이사가 확정한 날부터 시행한다.</p><h2 id="addendum3" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum3" aria-label="Permalink to &quot;부칙 {#addendum3 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2014. 12. 16.&gt;<br> 제1조(시행일) 본 내규는 대표이사가 확정한 날부터 시행한다.</p><h2 id="addendum4" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum4" aria-label="Permalink to &quot;부칙 {#addendum4 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2018. 11. 16.&gt;<br> 제1조(시행일) 본 내규는 대표이사가 확정한 날부터 시행한다.</p><h2 id="addendum5" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum5" aria-label="Permalink to &quot;부칙 {#addendum5 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2019. 11. 19.&gt;<br> 제1조(시행일) 본 내규는 대표이사가 확정한 날부터 시행한다.</p><h2 id="addendum6" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum6" aria-label="Permalink to &quot;부칙 {#addendum6 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2020. 12. 14.&gt;<br> 제1조(시행일) 본 내규는 대표이사가 확정한 날부터 시행한다.</p><h2 id="addendum7" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum7" aria-label="Permalink to &quot;부칙 {#addendum7 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2021. 12. 20.&gt;<br> 제1조(시행일) 본 내규는 대표이사가 확정한 날부터 시행한다.</p><h2 id="addendum8" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum8" aria-label="Permalink to &quot;부칙 {#addendum8 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2022. 12. 15.&gt;<br> 제1조(시행일) 본 내규는 대표이사가 확정한 날부터 시행한다.</p>`,39)]))}const g=r(n,[["render",o]]);export{b as __pageData,g as default};
